-- Reject special numeric values at the database boundary; NULL remains valid for unknown costs.
ALTER TABLE public.products ADD CONSTRAINT hardening_finite_products CHECK ((stock_qty IS NULL OR stock_qty::text NOT IN ('NaN','Infinity','-Infinity')) AND (min_stock IS NULL OR min_stock::text NOT IN ('NaN','Infinity','-Infinity')) AND (cost_price IS NULL OR cost_price::text NOT IN ('NaN','Infinity','-Infinity')) AND (selling_price IS NULL OR selling_price::text NOT IN ('NaN','Infinity','-Infinity')) AND (confidential_price IS NULL OR confidential_price::text NOT IN ('NaN','Infinity','-Infinity')) AND (mrp IS NULL OR mrp::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.stock_batches ADD CONSTRAINT hardening_finite_stock_batches CHECK ((qty IS NULL OR qty::text NOT IN ('NaN','Infinity','-Infinity')) AND (remaining_qty IS NULL OR remaining_qty::text NOT IN ('NaN','Infinity','-Infinity')) AND (purchase_price IS NULL OR purchase_price::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.stock_movements ADD CONSTRAINT hardening_finite_stock_movements CHECK ((quantity IS NULL OR quantity::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.sales ADD CONSTRAINT hardening_finite_sales CHECK ((subtotal IS NULL OR subtotal::text NOT IN ('NaN','Infinity','-Infinity')) AND (discount IS NULL OR discount::text NOT IN ('NaN','Infinity','-Infinity')) AND (tax IS NULL OR tax::text NOT IN ('NaN','Infinity','-Infinity')) AND (total IS NULL OR total::text NOT IN ('NaN','Infinity','-Infinity')) AND (amount_paid IS NULL OR amount_paid::text NOT IN ('NaN','Infinity','-Infinity')) AND (due_amount IS NULL OR due_amount::text NOT IN ('NaN','Infinity','-Infinity')) AND (finance_loan_amount IS NULL OR finance_loan_amount::text NOT IN ('NaN','Infinity','-Infinity')) AND (finance_net_receivable IS NULL OR finance_net_receivable::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.sale_items ADD CONSTRAINT hardening_finite_sale_items CHECK ((quantity IS NULL OR quantity::text NOT IN ('NaN','Infinity','-Infinity')) AND (unit_price IS NULL OR unit_price::text NOT IN ('NaN','Infinity','-Infinity')) AND (cost_price IS NULL OR cost_price::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.purchases ADD CONSTRAINT hardening_finite_purchases CHECK ((total IS NULL OR total::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.purchase_items ADD CONSTRAINT hardening_finite_purchase_items CHECK ((quantity IS NULL OR quantity::text NOT IN ('NaN','Infinity','-Infinity')) AND (purchase_price IS NULL OR purchase_price::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.returns ADD CONSTRAINT hardening_finite_returns CHECK ((quantity IS NULL OR quantity::text NOT IN ('NaN','Infinity','-Infinity')) AND (refund_amount IS NULL OR refund_amount::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.exchange_items ADD CONSTRAINT hardening_finite_exchange_items CHECK ((quantity IS NULL OR quantity::text NOT IN ('NaN','Infinity','-Infinity')) AND (unit_price IS NULL OR unit_price::text NOT IN ('NaN','Infinity','-Infinity')) AND (purchase_price IS NULL OR purchase_price::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.exchanges ADD CONSTRAINT hardening_finite_exchanges CHECK ((returned_value IS NULL OR returned_value::text NOT IN ('NaN','Infinity','-Infinity')) AND (replacement_value IS NULL OR replacement_value::text NOT IN ('NaN','Infinity','-Infinity')) AND (difference_amount IS NULL OR difference_amount::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.customer_payments ADD CONSTRAINT hardening_finite_customer_payments CHECK ((amount IS NULL OR amount::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.supplier_transactions ADD CONSTRAINT hardening_finite_supplier_transactions CHECK ((amount IS NULL OR amount::text NOT IN ('NaN','Infinity','-Infinity')));
